fn try_stderr_unit_err(error: io::Error) -> StderrUnitResult {
    let error = if error.kind() == io::ErrorKind::Interrupted {
        InterruptedOrStderrErr {
            payload: InterruptedOrStderrErrPayload { interrupted: [] },
            tag: InterruptedOrStderrErrTag::Interrupted,
        }
    } else {
        InterruptedOrStderrErr {
            payload: InterruptedOrStderrErrPayload {
                stderr_err: ManuallyDrop::new(stderr_io_err_from_io(&error, roc_host())),
            },
            tag: InterruptedOrStderrErrTag::StderrErr,
        }
    };
    StderrUnitResult {
        payload: StderrUnitResultPayload {
            err: ManuallyDrop::new(error),
        },
        tag: StderrUnitResultTag::Err,
    }
}

