/// Result of one read from standard input: `None` is the end of input.
fn stdin_read_result(
    result: io::Result<Option<Vec<u8>>>,
    roc_host: &RocHost,
) -> HostStdinBytesResult {
    let error = match result {
        Ok(Some(bytes)) => {
            return HostStdinBytesResult {
                payload: HostStdinBytesResultPayload {
                    ok: ManuallyDrop::new(roc_u8_list_from_slice(&bytes, roc_host)),
                },
                tag: HostStdinBytesResultTag::Ok,
            }
        }
        Ok(None) => EndOfInputOrInterruptedOrStdinErr {
            payload: EndOfInputOrInterruptedOrStdinErrPayload { end_of_input: [] },
            tag: EndOfInputOrInterruptedOrStdinErrTag::EndOfInput,
        },
        Err(error) if error.kind() == io::ErrorKind::Interrupted => {
            EndOfInputOrInterruptedOrStdinErr {
                payload: EndOfInputOrInterruptedOrStdinErrPayload { interrupted: [] },
                tag: EndOfInputOrInterruptedOrStdinErrTag::Interrupted,
            }
        }
        Err(error) => EndOfInputOrInterruptedOrStdinErr {
            payload: EndOfInputOrInterruptedOrStdinErrPayload {
                stdin_err: ManuallyDrop::new(stdin_io_err_from_io(&error, roc_host)),
            },
            tag: EndOfInputOrInterruptedOrStdinErrTag::StdinErr,
        },
    };
    HostStdinBytesResult {
        payload: HostStdinBytesResultPayload {
            err: ManuallyDrop::new(error),
        },
        tag: HostStdinBytesResultTag::Err,
    }
}

