#[no_mangle]
pub extern "C" fn roc_crashed(bytes: *const u8, len: usize) {
    // The default handler exits the process, so control never returns to
    // rust_main. Restore first so the crash message is not printed in raw mode.
    tty::restore();
    DefaultHandlers::roc_crashed(roc_host_ptr(), bytes, len);
}

#[cfg(unix)]
fn collect_process_args(argc: i32, argv: *const *const c_char) -> Vec<OsString> {
    if argc <= 0 || argv.is_null() {
        return Vec::new();
    }

    use std::os::unix::ffi::OsStringExt;

    let raw_args = unsafe { core::slice::from_raw_parts(argv, argc as usize) };
    raw_args
        .iter()
        .take_while(|arg| !arg.is_null())
        .map(|arg| unsafe { OsString::from_vec(CStr::from_ptr(*arg).to_bytes().to_vec()) })
        .collect()
}

#[cfg(windows)]
fn collect_process_args(_argc: i32, _argv: *const *const c_char) -> Vec<OsString> {
    std::env::args_os().collect()
}

#[cfg(not(any(unix, windows)))]
fn collect_process_args(_argc: i32, _argv: *const *const c_char) -> Vec<OsString> {
    Vec::new()
}

fn split_program_name(mut process_args: Vec<OsString>) -> (Option<OsString>, Vec<OsString>) {
    if process_args.is_empty() {
        (None, process_args)
    } else {
        let args = process_args.split_off(1);
        (process_args.pop(), args)
    }
}

fn build_args_list(args: &[OsString], roc_host: &RocHost) -> RocList<OsStr> {
    let list = unsafe { RocList::<OsStr>::allocate(args.len(), roc_host) };
    for (index, arg) in args.iter().enumerate() {
        #[cfg(unix)]
        use std::os::unix::ffi::OsStrExt;
        #[cfg(windows)]
        use std::os::windows::ffi::OsStrExt;

        unsafe {
            #[cfg(unix)]
            list.elements.add(index).write(OsStr {
                payload: OsStrPayload {
                    unix_bytes: ManuallyDrop::new(roc_u8_list_from_slice(
                        arg.as_os_str().as_bytes(),
                        roc_host,
                    )),
                },
                tag: OsStrTag::UnixBytes,
            });

            #[cfg(windows)]
            {
                let units = arg.encode_wide().collect::<Vec<_>>();
                list.elements.add(index).write(OsStr {
                    payload: OsStrPayload {
                        windows_u16s: ManuallyDrop::new(roc_u16_list_from_slice(&units, roc_host)),
                    },
                    tag: OsStrTag::WindowsU16s,
                });
            }

            #[cfg(not(any(unix, windows)))]
            list.elements.add(index).write(OsStr {
                payload: OsStrPayload {
                    utf8: ManuallyDrop::new(RocStr::empty()),
                },
                tag: OsStrTag::Utf8,
            });
        }
    }
    list
}

#[cfg(not(test))]
#[no_mangle]
pub extern "C" fn main(argc: i32, argv: *const *const c_char) -> i32 {
    rust_main(argc, argv)
}

#[cfg(unix)]
extern "C" fn ignore_sigpipe(_: libc::c_int) {}

pub fn rust_main(argc: i32, argv: *const *const c_char) -> i32 {
    // Unlike a Rust executable, this C-ABI entrypoint does not pass through
    // std::rt's signal initialization. Return BrokenPipe from our I/O effects.
    // A caught no-op disposition also resets on successful execv, while a failed
    // replacement preserves BrokenPipe behavior without changing process state.
    #[cfg(unix)]
    unsafe {
        libc::signal(
            libc::SIGPIPE,
            ignore_sigpipe as *const () as libc::sighandler_t,
        );
    }
    let mut roc_host = resources::make_host();
    set_roc_host(&mut roc_host);
    resources::bind_host_thread();

    let (program_name, args) = split_program_name(collect_process_args(argc, argv));
    set_program_name(program_name);

    let args_list = build_args_list(&args, &roc_host);
    // A host panic aborts the process in release builds, skipping the cleanup
    // below, so the hook is the only chance to hand the terminal back.
    let default_panic_hook = std::panic::take_hook();
    std::panic::set_hook(Box::new(move |info| {
        tty::restore();
        default_panic_hook(info);
    }));

    let mut exit_code = unsafe { roc_main(args_list) };

    // Covers a normal return, an application error, and an explicit exit code.
    tty::restore();

    process_service::shutdown();

    // Everything `main!` opened should be released by now, whichever way it
    // returned. A crash exits inside `roc_crashed` and is not reported.
    resources::report_live_handles_if_requested();

    if DEBUG_OR_EXPECT_CALLED.load(Ordering::Acquire) && exit_code == 0 {
        exit_code = 1;
    }

    set_program_name(None);
    set_roc_host(core::ptr::null_mut());
    exit_code
}

pub(crate) fn monotonic_origin() -> std::time::Instant {
    static ORIGIN: std::sync::OnceLock<std::time::Instant> = std::sync::OnceLock::new();
    *ORIGIN.get_or_init(std::time::Instant::now)
}

#[no_mangle]
pub extern "C" fn hosted_monotonic_now() -> u64 {
    u64::try_from(monotonic_origin().elapsed().as_nanos()).unwrap_or(u64::MAX)
}

#[no_mangle]
pub extern "C" fn hosted_system_target() -> SystemTarget {
    #[cfg(target_os = "linux")]
    let operating_system = LinuxOrMacOSOrWindows {
        payload: LinuxOrMacOSOrWindowsPayload {
            linux: ManuallyDrop::new(SystemLinux { proof: 0 }),
        },
        tag: LinuxOrMacOSOrWindowsTag::Linux,
    };
    #[cfg(target_os = "macos")]
    let operating_system = LinuxOrMacOSOrWindows {
        payload: LinuxOrMacOSOrWindowsPayload {
            mac_os: ManuallyDrop::new(SystemMacOS { proof: 0 }),
        },
        tag: LinuxOrMacOSOrWindowsTag::MacOS,
    };
    #[cfg(windows)]
    let operating_system = LinuxOrMacOSOrWindows {
        payload: LinuxOrMacOSOrWindowsPayload {
            windows: ManuallyDrop::new(SystemWindows { proof: 0 }),
        },
        tag: LinuxOrMacOSOrWindowsTag::Windows,
    };
    SystemTarget {
        architecture: if cfg!(target_arch = "aarch64") {
            Arm64OrX64::Arm64
        } else {
            Arm64OrX64::X64
        },
        operating_system,
    }
}

#[no_mangle]
pub extern "C" fn hosted_signal_catch(
    requests: RocListWith<HostSignalCatchArg0, false>,
) -> HostSignalCatchResult {
    let mut bits = 0;
    for request in requests.as_slice() {
        bits |= match request.tag {
            HostSignalCatchArg0Tag::Interrupt => signals::INTERRUPT,
            HostSignalCatchArg0Tag::Terminate => signals::TERMINATE,
        };
    }
    unsafe { requests.decref(roc_host()) };
    match (if bits == 0 {
        Ok(())
    } else {
        native_stdio::prepare()
    })
    .and_then(|()| signals::catch(bits))
    {
        Ok(()) => HostSignalCatchResult {
            payload: HostSignalCatchResultPayload { ok: [] },
            tag: HostSignalCatchResultTag::Ok,
        },
        Err(error) => HostSignalCatchResult {
            payload: HostSignalCatchResultPayload {
                err: ManuallyDrop::new(env_io_err_from_io(&error, roc_host())),
            },
            tag: HostSignalCatchResultTag::Err,
        },
    }
}

#[no_mangle]
pub extern "C" fn hosted_signal_poll() -> RocListWith<HostSignalPoll, false> {
    let bits = signals::poll();
    let mut events = Vec::new();
    if bits & signals::INTERRUPT != 0 {
        events.push(HostSignalPoll::Interrupt);
    }
    if bits & signals::TERMINATE != 0 {
        events.push(HostSignalPoll::Terminate);
    }
    unsafe { RocListWith::from_slice(&events, roc_host()) }
}

#[no_mangle]
pub extern "C" fn hosted_path_set_permissions(
    path: NativeOsStr,
    permissions: OwnerOnlyOrPublicRead,
) -> HostPathSetPermissionsResult {
    let result = path_from_native(path, roc_host()).and_then(|path| {
        file_security::set_permissions(
            &path,
            match permissions {
                OwnerOnlyOrPublicRead::OwnerOnly => file_security::Policy::OwnerOnly,
                OwnerOnlyOrPublicRead::PublicRead => file_security::Policy::PublicRead,
            },
        )
    });
    path_unit_result(result)
}

fn path_unit_result(result: io::Result<()>) -> HostPathSetPermissionsResult {
    match result {
        Ok(()) => HostPathSetPermissionsResult {
            payload: HostPathSetPermissionsResultPayload { ok: [] },
            tag: HostPathSetPermissionsResultTag::Ok,
        },
        Err(error) => HostPathSetPermissionsResult {
            payload: HostPathSetPermissionsResultPayload {
                err: ManuallyDrop::new(path_io_err_from_io(&error, roc_host())),
            },
            tag: HostPathSetPermissionsResultTag::Err,
        },
    }
}
#[no_mangle]
pub extern "C" fn hosted_path_symlink(
    target: NativeOsStr,
    link: NativeOsStr,
    kind: DirectoryOrFile,
) -> HostPathSymlinkResult {
    let target = path_from_native(target, roc_host());
    let link = path_from_native(link, roc_host());
    path_unit_result(target.and_then(|target| {
        link.and_then(|link| {
            filesystem::symlink(&target, &link, kind == DirectoryOrFile::Directory)
        })
    }))
}
#[no_mangle]
pub extern "C" fn hosted_path_read_link(path: NativeOsStr) -> HostPathReadLinkResult {
    match path_from_native(path, roc_host()).and_then(|path| filesystem::read_link(&path)) {
        Ok(path) => HostPathReadLinkResult {
            payload: HostPathReadLinkResultPayload {
                ok: ManuallyDrop::new(native_path_from_path(&path, roc_host())),
            },
            tag: HostPathReadLinkResultTag::Ok,
        },
        Err(error) => HostPathReadLinkResult {
            payload: HostPathReadLinkResultPayload {
                err: ManuallyDrop::new(path_io_err_from_io(&error, roc_host())),
            },
            tag: HostPathReadLinkResultTag::Err,
        },
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::path::{Path, PathBuf};
    use std::sync::atomic::{AtomicUsize, Ordering};

    static NEXT_TEST_DIR: AtomicUsize = AtomicUsize::new(0);

    #[test]
    fn directory_iteration_error_is_not_silently_dropped() {
        let entries = [
            Ok(PathBuf::from("first")),
            Err(io::Error::from(io::ErrorKind::PermissionDenied)),
            Ok(PathBuf::from("last")),
        ];
        assert_eq!(
            collect_directory_entries(entries).unwrap_err().kind(),
            io::ErrorKind::PermissionDenied
        );
    }

    #[test]
    fn nanos_since_epoch_is_signed_around_the_epoch() {
        use std::time::{Duration, UNIX_EPOCH};

        assert_eq!(nanos_since_epoch(UNIX_EPOCH), Some(0));
        assert_eq!(
            nanos_since_epoch(UNIX_EPOCH + Duration::new(1, 500_000_000)),
            Some(1_500_000_000)
        );
        // 100 ns is the finest step a Windows `SystemTime` can hold.
        assert_eq!(
            nanos_since_epoch(UNIX_EPOCH + Duration::from_nanos(100)),
            Some(100)
        );
        // 2026-10-13T09:30:00Z.
        assert_eq!(
            nanos_since_epoch(UNIX_EPOCH + Duration::from_secs(1_791_883_800)),
            Some(1_791_883_800_000_000_000)
        );
    }

    #[test]
    fn nanos_since_epoch_is_negative_before_the_epoch() {
        use std::time::{Duration, UNIX_EPOCH};

        assert_eq!(
            nanos_since_epoch(UNIX_EPOCH - Duration::from_secs(1)),
            Some(-1_000_000_000)
        );
        assert_eq!(
            nanos_since_epoch(UNIX_EPOCH - Duration::new(1, 500_000_000)),
            Some(-1_500_000_000)
        );
        // 1900-01-01T00:00:00Z.
        assert_eq!(
            nanos_since_epoch(UNIX_EPOCH - Duration::from_secs(2_208_988_800)),
            Some(-2_208_988_800_000_000_000)
        );
    }

    #[test]
    fn file_time_before_the_epoch_is_negative_not_an_error() {
        let test_dir = TestDir::new();
        let path = test_dir.join("old.txt");
        fs::write(&path, b"old").unwrap();

        // 1969-12-31T00:00:00Z, one day before the epoch.
        let before_epoch = std::time::UNIX_EPOCH - std::time::Duration::from_secs(86_400);
        let file = fs::File::options().write(true).open(&path).unwrap();
        file.set_modified(before_epoch).unwrap();
        drop(file);

        let modified = fs::metadata(&path).unwrap().modified().unwrap();
        assert_eq!(nanos_since_epoch(modified), Some(-86_400_000_000_000));
    }

    struct TestDir(PathBuf);

    impl TestDir {
        fn new() -> Self {
            let sequence = NEXT_TEST_DIR.fetch_add(1, Ordering::Relaxed);
            let path = std::env::temp_dir().join(format!(
                "basic-cli-path-type-{}-{sequence}",
                std::process::id()
            ));
            fs::create_dir(&path).unwrap();
            Self(path)
        }

        fn join(&self, path: impl AsRef<Path>) -> PathBuf {
            self.0.join(path)
        }
    }

    impl Drop for TestDir {
        fn drop(&mut self) {
            fs::remove_dir_all(&self.0).unwrap();
        }
    }

    fn classify(path: &Path) -> PathType {
        path_type_from_metadata(&path.symlink_metadata().unwrap())
    }

    fn strings(values: &[&str]) -> Vec<String> {
        values.iter().map(|value| (*value).to_string()).collect()
    }

    #[test]
    fn lists_every_directory_entry() {
        let directory = TestDir::new();
        fs::write(directory.join("file"), b"contents").unwrap();
        fs::create_dir(directory.join("child")).unwrap();

        let mut entries = list_directory(&directory.0).unwrap();
        entries.sort();

        assert_eq!(entries, [directory.join("child"), directory.join("file")]);
    }

    #[test]
    fn lists_an_empty_directory() {
        let directory = TestDir::new();

        assert!(list_directory(&directory.0).unwrap().is_empty());
    }

    #[test]
    fn listing_a_regular_file_reports_not_a_directory() {
        let directory = TestDir::new();
        let file = directory.join("file");
        fs::write(&file, b"contents").unwrap();

        assert_eq!(
            list_directory(&file).unwrap_err().kind(),
            io::ErrorKind::NotADirectory
        );
    }

    #[test]
    fn listing_a_missing_directory_reports_not_found() {
        let directory = TestDir::new();

        assert_eq!(
            list_directory(&directory.join("missing"))
                .unwrap_err()
                .kind(),
            io::ErrorKind::NotFound
        );
    }

    #[test]
    fn separates_program_name_from_command_line_arguments() {
        let (program_name, args) = split_program_name(vec![
            OsString::from("roc-app"),
            OsString::from("first"),
            OsString::from("second"),
        ]);

        assert_eq!(program_name, Some(OsString::from("roc-app")));
        assert_eq!(args, [OsString::from("first"), OsString::from("second")]);
    }

    #[test]
    fn reports_an_unavailable_program_name_for_an_empty_process_argument_list() {
        let (program_name, args) = split_program_name(Vec::new());

        assert_eq!(program_name, None);
        assert!(args.is_empty());
    }

    #[cfg(unix)]
    #[test]
    fn collects_process_arguments_without_losing_non_utf8_bytes() {
        use std::ffi::CString;
        use std::os::unix::ffi::OsStringExt;

        let values = [
            CString::new(b"launcher-name".as_slice()).unwrap(),
            CString::new(vec![b'a', 0xff, b'b']).unwrap(),
        ];
        let pointers = values
            .iter()
            .map(|value| value.as_ptr())
            .collect::<Vec<_>>();

        assert_eq!(
            collect_process_args(pointers.len() as i32, pointers.as_ptr()),
            [
                OsString::from("launcher-name"),
                OsString::from_vec(vec![b'a', 0xff, b'b']),
            ]
        );
    }

    #[test]
    fn normalizes_posix_locale_forms() {
        assert_eq!(normalize_locale("en_US"), Some("en-US".to_string()));
        assert_eq!(normalize_locale("sr_RS.UTF-8"), Some("sr-RS".to_string()));
        assert_eq!(normalize_locale("de_DE@euro"), Some("de-DE".to_string()));
        assert_eq!(
            normalize_locale("ca_ES.UTF-8@valencia"),
            Some("ca-ES".to_string())
        );
    }

    #[test]
    fn rejects_non_language_and_malformed_host_locales() {
        for input in [
            "",
            " ",
            "C",
            "C.UTF-8",
            "POSIX",
            "en--US",
            "1-US",
            "en_US!",
            "en-abcdefghi",
            "en-u",
        ] {
            assert_eq!(normalize_locale(input), None, "accepted {input:?}");
        }
    }

    #[test]
    fn accepts_representative_macos_and_windows_tags() {
        for input in ["en-US", "zh-Hant-TW", "de-DE", "x-private"] {
            assert_eq!(normalize_locale(input), Some(input.to_string()));
        }
    }

    #[test]
    fn filters_invalid_locales_and_deduplicates_normalized_values() {
        assert_eq!(
            normalize_locales(strings(&[
                "C.UTF-8",
                "en_US.UTF-8",
                "EN-us",
                "malformed!",
                "fr_FR@euro",
            ])),
            strings(&["en-US", "fr-FR"])
        );
    }

    #[test]
    fn classifies_regular_files_and_directories() {
        let directory = TestDir::new();
        let file = directory.join("file");
        fs::write(&file, b"contents").unwrap();

        assert_eq!(classify(&directory.0), PathType::Dir);
        assert_eq!(classify(&file), PathType::File);
    }

    #[cfg(unix)]
    #[test]
    fn classifies_symbolic_links() {
        use std::os::unix::fs::symlink;

        let directory = TestDir::new();
        let target = directory.join("target");
        let link = directory.join("link");
        fs::write(&target, b"contents").unwrap();
        symlink(&target, &link).unwrap();

        assert_eq!(classify(&link), PathType::SymLink);
    }

    #[cfg(unix)]
    #[test]
    fn classifies_fifo_as_other() {
        use std::ffi::CString;
        use std::os::unix::ffi::OsStrExt;

        let directory = TestDir::new();
        let fifo = directory.join("fifo");
        let fifo_c_string = CString::new(fifo.as_os_str().as_bytes()).unwrap();
        let result = unsafe { libc::mkfifo(fifo_c_string.as_ptr(), 0o600) };
        assert_eq!(result, 0, "mkfifo failed: {}", io::Error::last_os_error());

        assert_eq!(classify(&fifo), PathType::Other);
    }

    #[cfg(unix)]
    #[test]
    fn classifies_unix_domain_socket_as_other() {
        use std::os::unix::net::UnixListener;

        let directory = TestDir::new();
        let socket = directory.join("socket");
        let _listener = UnixListener::bind(&socket).unwrap();

        assert_eq!(classify(&socket), PathType::Other);
    }
}
